import { fieldHelp } from './field-help.ts'

export type HelpBlock =
  | { kind: 'paragraph' | 'heading' | 'note' | 'code'; text: string }
  | { kind: 'list' | 'steps'; items: string[] }
  | { kind: 'table'; columns: string[]; rows: string[][] }
export interface HelpChapter { id: string; group: string; title: string; summary: string; blocks: HelpBlock[] }
const p = (text: string): HelpBlock => ({ kind: 'paragraph', text })
const h = (text: string): HelpBlock => ({ kind: 'heading', text })
const note = (text: string): HelpBlock => ({ kind: 'note', text })
const code = (text: string): HelpBlock => ({ kind: 'code', text })
const list = (...items: string[]): HelpBlock => ({ kind: 'list', items })
const steps = (...items: string[]): HelpBlock => ({ kind: 'steps', items })
const table = (columns: string[], rows: string[][]): HelpBlock => ({ kind: 'table', columns, rows })

